class r{constructor(i,t){if(t>i)throw new Error("Min granularity must not be greater than base granularity.");this._baseZoomGranularity=i,this._minGranularity=t}getGranularityForZoomLevel(i){const t=1<<i;return Math.max(Math.floor(this._baseZoomGranularity/t),this._minGranularity,1)}}const e=class e{constructor(i){this.fill=i.fill,this.line=i.line,this.tile=i.tile,this.stencil=i.stencil,this.circle=i.circle}};e.noSubdivision=new e({fill:new r(0,0),line:new r(0,0),tile:new r(0,0),stencil:new r(0,0),circle:1});let l=e;export{r as SubdivisionGranularityExpression,l as SubdivisionGranularitySetting};
